timeline('Arunachal Pradesh|Assam',
    ('24 Feb 1826', 'The Treaty of Yandabo ends the First Anglo-Burmese War: Burma renounces all claims to Assam, which comes under British control.', ['ne_yandabo']),
    ('Feb 1874', 'Assam is separated from Bengal as its own Chief Commissioner’s province, joining the plains districts and the surrounding hill and frontier tracts under one administration.', ['ne_assamprov']),
    ('1914–19', 'The North-East Frontier Tract is carved out of Darrang and Lakhimpur districts to separate the Assam plains from the tribal hills; in 1919 it is reorganised into the Balipara and Sadiya Frontier Tracts.', ['ne_neft']),
    ('1951', 'Acting on the Bordoloi Sub-Committee’s report, the government transfers the plains portions of the Balipara and Sadiya foothills — about 3,648 km² — to Assam’s Darrang and Lakhimpur districts. Assam still treats this notified line as the boundary; Arunachal Pradesh says the transfer was made without consulting the hill chiefs who held the land.', ['ne_neft', 'ne_apdispute']),
    ('1954', 'The frontier tracts are brought together and renamed the North-East Frontier Agency (NEFA), administered through the Ministry of External Affairs.', ['ne_neft']),
    ('21 Jan 1972', 'Under the North-Eastern Areas (Reorganisation) Act, 1971, NEFA becomes the Union Territory of Arunachal Pradesh, formally separating it from Assam along the 1951 line.', ['m7']),
    ('1989–2007', 'Assam takes the boundary dispute to the Supreme Court; in 2006 the Court appoints a local boundary commission, before which Arunachal Pradesh in 2007 lists 123 disputed villages spread across 12 of its districts and 8 of Assam’s.', ['ne_apdispute']),
    ('15 Jul 2022', 'The Namsai Declaration agrees in principle on 37 of the 123 villages: 28 stay with Arunachal Pradesh and 3 with Assam.', ['ne_namsai']),
    ('20 Apr 2023', 'An MoU signed by both chief ministers before the Union Home Minister resolves 71 of the 123 claimed villages, including the Namsai 37; timelines are fixed for finalising the rest through joint regional committees.', ['m30', 'ne_namsai']),
    ('2020s', 'Assam and Arunachal Pradesh share an 804.1 km boundary; the Assam government’s border-dispute page tracks the still-unresolved villages.', ['m15', 'm16']),
)

timeline('Assam|Nagaland',
    ('1866', 'The British form the Naga Hills District, based first at Samaguting and from 1878 at Kohima, to curb raids on the Assam plains; over the following decades its line against the neighbouring plains districts is redrawn repeatedly, including large transfers of the Nambor Forest and Rengma Hills reserves to Sibsagar and Nowgong between 1898 and 1903.', ['ne_naga1866', 'ne_1925notif']),
    ('25 Nov 1925', 'A notification fixes the Naga Hills District’s boundary against Sibsagar and Nowgong, confirming those earlier forest transfers — the line later written into Nagaland’s founding statute.', ['ne_1925notif']),
    ('26–28 Jun 1947', 'Point 6 of the Naga–Akbar Hydari Nine-Point Agreement, signed by the Naga National Council and Assam’s governor, promises to bring the transferred forests back into the Naga Hills and unify the Naga-inhabited areas; the Naga side says this was never carried out.', ['ne_hydari']),
    ('1960', 'Points 12–13 of the 16-Point Agreement between the Naga People’s Convention and the Union government again record the demand to restore the transferred areas; the government instead moves ahead with statehood.', ['ne_16point']),
    ('1962', 'The State of Nagaland Act defines the new state’s boundary by reference to the 1925 notification; Nagaland becomes a state on 1 December 1963 but has never accepted that line.', ['m5']),
    ('1979', 'After repeated clashes, a roughly 10-km-wide Disputed Area Belt — sectors A (Diphu Reserve Forest), B (South Nambor Reserve Forest) and C (Rengma Reserve Forest) — is placed under CRPF policing.', ['m15']),
    ('1985', 'The Merapani incident kills 41 people, 28 of them police; the Shastri Commission is set up, followed over the years by the Pillai, Variava and Chatterjee commissions, none of which end the dispute.', ['ne_neborders']),
    ('1988', 'Assam files Original Suit No. 2/1988 in the Supreme Court seeking a boundary settlement with Nagaland.', ['m15']),
    ('2014', 'Clashes around the disputed belt kill 17 people and displace about 10,000.', ['ne_neborders']),
    ('2020s', 'Original Suit No. 2/1988 remains at the trial stage before the Supreme Court; the Government of Assam’s border-dispute page gives the current status of this and Assam’s other boundary disputes.', ['m15']),
)

timeline('Assam|Meghalaya',
    ('British period', 'Colonial Assam administers the United Khasi and Jaintia Hills District and the Garo Hills District as two of its hill districts.', ['ne_assamprov']),
    ('13 Apr 1951', 'Acting on the Bordoloi committee’s recommendations, a Government of Assam notification transfers Blocks I and II of the Jaintia Hills to the Mikir Hills (Karbi Anglong) and parts of the Garo Hills to Goalpara district.', ['ne_meghdispute']),
    ('1969', 'The Assam Reorganisation (Meghalaya) Act defines Meghalaya as the United Khasi-Jaintia Hills District (excluding the 1951 transfer) plus the Garo Hills District; Meghalaya later rejects this basis, preferring 1872 and 1929 survey maps and 1878 notifications.', ['ne_araa1969', 'ne_langpih']),
    ('21 Jan 1972', 'Meghalaya becomes a full state under the North-Eastern Areas (Reorganisation) Act, 1971, and the 1969 district lines become the interstate boundary; Meghalaya identifies 12 “areas of difference” covering about 2,700 km², including Langpih, disputed since 1974.', ['m7', 'ne_langpih']),
    ('29 Mar 2022', 'An MoU between the two states settles six of the twelve areas — Tarabari, Gizang, Hahim, Boklapara, Khanapara–Pillangkata and Ratacherra — splitting 36.79 km² into 18.51 km² for Assam and 18.28 km² for Meghalaya.', ['m25']),
    ('30 Jun 2026', 'Meghalaya reconstitutes three regional committees to examine the six areas of difference still unresolved, including Langpih, Borduar and Block I–II of the Jaintia Hills.', ['m17']),
    ('2020s', 'The two states share an 884.9 km border; the Government of Assam’s border-dispute page tracks the outstanding areas.', ['m15', 'm16']),
)

timeline('Assam|Mizoram',
    ('1871–72', 'Cachar’s deputy commissioner John Ware Edgar reaches a boundary understanding with Lushai chief Suakpuilala, the earliest attempt to fix a line between the Cachar plains and the Lushai Hills.', ['ne_neborders']),
    ('1873', 'The Bengal Eastern Frontier Regulation creates the Inner Line, separating the administered Cachar plains from the hill tracts that become the Lushai Hills.', ['ne_innerline']),
    ('1889–98', 'After the Chin-Lushai expedition, North Lushai Hills (under Assam) and South Lushai Hills (under Bengal) are formed; the two merge into one Lushai Hills district under Assam on 1 April 1898.', ['ne_lushai']),
    ('Aug 1875', 'A notification fixes Cachar district’s southern boundary under the 1873 Regulation, drawn in consultation with Mizo chiefs; Mizoram treats this as the correct line today.', ['m15']),
    ('Mar 1933', 'A separate notification demarcates the Lushai Hills–Manipur boundary without Mizo consultation; Assam treats this line, as later operationalised in a 1986–87 demarcation, as the correct one.', ['m15']),
    ('21 Jan 1972', 'Mizoram becomes a Union Territory carved out of Assam under the North-Eastern Areas (Reorganisation) Act, 1971, inheriting the unresolved question of which colonial notification applies.', ['m7']),
    ('1987', 'Mizoram gains full statehood following the Mizoram Peace Accord.', ['ne_neborders']),
    ('26 Jul 2021', 'Firing at Lailapur–Vairengte kills seven people — six Assam policemen and a civilian — and injures dozens; the roughly 164.6 km border includes about 509 sq miles of disputed inner-line reserve forest.', ['m15']),
    ('9 Aug 2024', 'Assam and Mizoram sign a joint statement committing to continue peaceful negotiations toward a settlement.', ['m18']),
)

timeline('Assam|Manipur',
    ('24 Feb 1826', 'The Treaty of Yandabo also covers Manipur: Burma renounces its claims there, and with British help Raja Gambhir Singh is restored, leaving Manipur a British-protected state next to the British district of Cachar.', ['ne_yandabo', 'ne_manipurps']),
    ('1835', 'The British station a Political Agent at Imphal; from this period Manipur’s western limit against Cachar (later part of Assam) is treated as a settled frontier.', ['ne_manipurps']),
    ('1891', 'After the Anglo-Manipur War, Manipur is reduced to a princely state under full British paramountcy, still bordering Assam’s Cachar district on the same line.', ['ne_angloman']),
    ('21 Sep 1949', 'The Manipur Merger Agreement, effective 15 October 1949, brings Manipur into the Indian Union as a Part C State under a Chief Commissioner, freezing its old princely-state limits — including the Cachar frontier — as an internal administrative line.', ['m34']),
    ('1956', 'The States Reorganisation Act makes Manipur a Union Territory administered directly by the Union.', ['ne_manipurhist']),
    ('21 Jan 1972', 'The North-Eastern Areas (Reorganisation) Act, 1971 grants Manipur statehood, turning the old Manipur–Cachar princely-state line into a full interstate boundary with Assam.', ['m7']),
    ('2020s', 'Unlike Assam’s other neighbours, this stretch has no active territorial dispute; it remains defined by the limits frozen at the 1949 merger.', ['m1', 'm34']),
)

timeline('Assam|Tripura',
    ('1809', 'Tripura (Hill Tippera) becomes a British protectorate under subsidiary alliance; its plains estate, Chakla Roshnabad, lies in the Bengal districts of Noakhali, Sylhet and Tippera, while the hill kingdom’s northern frontier faces the Kachari kingdom of Cachar.', ['ne_tripuraps']),
    ('14 Aug 1832', 'Cachar is annexed to British India after its king dies without an heir, fixing a British-administered district immediately north of the Tripura hill state.', ['ne_cachar1832']),
    ('1905', 'Hill Tippera becomes part of the new province of Eastern Bengal and Assam, placing Tripura and Cachar under the same regional administration without merging them.', ['ne_tripuraps']),
    ('1947', 'Maharaja Bir Bikram Kishore Debbarman dies; a Council of Regency under Maharani Kanchan Prava Devi governs Tripura, released from subsidiary alliance by the Indian Independence Act, 1947.', ['ne_tripuramerger']),
    ('9 Sep 1949', 'The Tripura Merger Agreement, effective 15 October 1949, brings the state into the Indian Union as a Part C State under a Chief Commissioner, freezing its old frontier with Cachar as an internal administrative line.', ['m1', 'ne_tripuramerger']),
    ('1956', 'Tripura becomes a Union Territory.', ['ne_tripuramerger']),
    ('21 Jan 1972', 'The North-Eastern Areas (Reorganisation) Act, 1971 gives Tripura statehood, turning the frozen princely-state line into a full interstate boundary with Assam.', ['m7']),
    ('2020s', 'As with Assam’s Manipur boundary, no active territorial dispute is recorded on this frontier; it remains the line fixed at the 1949 merger.', ['m1']),
)

timeline('Assam|West Bengal',
    ('1822', 'Goalpara district is created by David Scott out of the former Bijni kingdom, administered as part of the North-East Rangpur division.', ['ne_goalpara']),
    ('1866', 'Garo Hills is separated from Goalpara, and the residual Goalpara territory is withdrawn from Rangpur and attached to Cooch Behar.', ['ne_goalpara']),
    ('1874', 'With the creation of the Assam Chief Commissioner’s province, Goalpara is withdrawn from Cooch Behar and attached to Assam, fixing the district’s western edge against the Cooch Behar and Jalpaiguri territory that stays in Bengal.', ['ne_goalpara', 'ne_assamprov']),
    ('Aug 1947', 'The Bengal Boundary Commission’s Radcliffe award reorganises Bengal’s eastern and southern frontiers (including Sylhet, after its referendum) but leaves the Goalpara–Cooch Behar/Jalpaiguri sector untouched.', ['m13']),
    ('28 Aug 1949', 'The Maharaja of Cooch Behar cedes full authority over his state to the Dominion of India.', ['ne_coochbehar']),
    ('12 Sep 1949', 'Administration of Cooch Behar formally passes to the Government of India.', ['ne_coochbehar']),
    ('19 Jan 1950', 'Cooch Behar is merged into the province of West Bengal as a new district, fixing its boundary with Goalpara (Assam) as the present interstate line.', ['ne_coochbehar']),
    ('2020s', 'The Government of Assam’s official boundary records describe this Goalpara/Cooch Behar–Jalpaiguri line as the current Assam–West Bengal border.', ['m16']),
)

timeline('Arunachal Pradesh|Nagaland',
    ('to 1947', 'Tuensang is an “Excluded Area” under British rule, with little outside administration, distinct from the administered Naga Hills District to its west.', ['ne_tuensang']),
    ('1948', 'The first administrative post is set up at Tuensang.', ['ne_tuensang']),
    ('early 1950s', 'Tuensang — with the areas later split off as Mon, Longleng and Kiphire — is placed within NEFA as the Tuensang Frontier Division, next to NEFA’s Tirap Frontier Division to its south.', ['ne_tuensang']),
    ('1 Dec 1957', 'The Tuensang Frontier Division is taken out of NEFA and merged with the Naga Hills District of Assam to form the centrally governed Naga Hills-Tuensang Area (NHTA); the line left between Tuensang and NEFA’s neighbouring Tirap division becomes the seed of today’s Arunachal–Nagaland border.', ['ne_tuensang']),
    ('1960', 'The 16-Point Agreement between the Naga People’s Convention and the Government of India sets out the path to statehood for the NHTA.', ['ne_16point']),
    ('1 Dec 1963', 'The NHTA becomes the state of Nagaland, India’s 16th state, while Tirap remains part of NEFA.', ['ne_tuensang', 'm5']),
    ('21 Jan 1972', 'The North-Eastern Areas (Reorganisation) Act, 1971 makes NEFA the Union Territory of Arunachal Pradesh, formalising the 1957 NHTA/Tirap line as an interstate boundary.', ['m7']),
    ('2020s', 'No territorial dispute is recorded on this stretch; security concerns instead centre on Naga insurgent activity in the neighbouring Tirap, Changlang and Longding districts, where AFSPA remains in force.', ['ne_arunsecurity']),
)

timeline('Manipur|Nagaland',
    ('British period', 'The Naga Hills District (formed 1866) borders the princely state of Manipur; the line divides Naga-inhabited country between direct British administration and Manipur’s own darbar administration, without regard to individual Naga clan and village territories.', ['ne_naga1866', 'ne_maoangami']),
    ('1891', 'After the Anglo-Manipur War, Manipur becomes a full princely state under British paramountcy; the Naga Hills–Manipur line continues as an internal administrative boundary within British India.', ['ne_angloman']),
    ('21 Sep 1949', 'The Manipur Merger Agreement freezes the state’s limits, including this Naga Hills frontier, as Manipur joins the Indian Union.', ['m34']),
    ('1 Dec 1963', 'Nagaland statehood turns the old Naga Hills District/Manipur line into a full interstate boundary; because it split Naga communities without regard to clan territory, the Mao Naga (Manipur) and Southern Angami (Nagaland) dispute ownership of the Kezoltsa forest and parts of the Dzükou valley that straddle it.', ['m5', 'ne_maoangami']),
    ('1985', 'The first recorded clash over the Dzükou valley occurs when a Manipur government team visiting the area is detained by Angami villagers.', ['ne_maoangami']),
    ('2015', 'The Mao Council alleges encroachment in the Kezoltsa forest, triggering an economic blockade.', ['ne_maoangami']),
    ('2016–2022', 'The Tenyimi People’s Organisation, a traditional Naga body representing both communities, holds more than 30 arbitration sittings, using drone and helicopter surveys to map the disputed forest.', ['ne_maoangami']),
    ('Jul–Sep 2024', 'The Organisation’s verdict of 12 July 2024 divides the Kezoltsa forest among the Southern Angami, Mao and Maram Khullen communities; the Mao Council accepts it on 23 September 2024.', ['ne_maoangami']),
)

timeline('Manipur|Mizoram',
    ('1891', 'After the Anglo-Manipur War, Manipur becomes a princely state under full British paramountcy, bordering the future Lushai Hills to its west.', ['ne_angloman']),
    ('1 Apr 1898', 'North and South Lushai Hills merge into a single Lushai Hills district under Assam, fronting Manipur along an as-yet unsurveyed line.', ['ne_lushai']),
    ('Mar 1933', 'A notification demarcates the Lushai Hills–Manipur boundary, starting from the trijunction of the Lushai Hills, Cachar district and Manipur state; it is issued without consulting Mizo society, a point Mizo leaders still raise about Assam’s use of the same line.', ['ne_manmizo33']),
    ('21 Sep 1949', 'The Manipur Merger Agreement freezes the state’s limits, including this Lushai Hills frontier, as Manipur joins the Indian Union.', ['m34']),
    ('21 Jan 1972', 'The North-Eastern Areas (Reorganisation) Act, 1971 gives Manipur full statehood and makes the Lushai Hills the Union Territory of Mizoram, turning the 1933 line into a full interstate boundary.', ['m7']),
    ('1987', 'Mizoram gains full statehood under the Mizoram Peace Accord.', ['ne_neborders']),
    ('since 1995', 'Assam and Mizoram hold repeated, inconclusive talks over the same 1933 notification; no comparable territorial dispute is recorded between Manipur and Mizoram themselves.', ['ne_manmizo33']),
    ('since May 2023', 'Manipur’s ethnic conflict displaces thousands of Kuki-Zo people across this border into Mizoram, whose Mizo majority shares close ethnic ties with them — a humanitarian rather than a territorial issue.', ['ne_mizorefugee']),
)

timeline('Mizoram|Tripura',
    ('before 1890', 'Mizo clans are distributed politically between the princely state of Hill Tipperah (Tripura) and the Chittagong Hill Tracts, with no fixed line between them.', ['ne_lushaitripura']),
    ('27 Jan 1871', 'A Lushai raid on the Alexandrapore tea estate in southern Assam pushes the British toward a permanent administrative solution for the Lushai country.', ['ne_lushaitripura']),
    ('1889–90', 'The British annex the Lushai country, separating the eastern portion of Hill Tipperah and joining it with the Lushai tracts of Chittagong to form the new Lushai Hills district — fixing a line against princely Tripura for the first time.', ['ne_lushaitripura', 'ne_lushai']),
    ('1891–1947', 'Lushai Hills is governed as a Backward Tract, later an Excluded Area, directly under the Governor of Assam, while Hill Tipperah remains a separate princely state on the other side of the 1890 line.', ['ne_lushaiexcluded']),
    ('9 Sep 1949', 'The Tripura Merger Agreement freezes the state’s limits, including this Lushai Hills frontier, as Tripura joins the Indian Union.', ['m1', 'ne_tripuramerger']),
    ('21 Jan 1972', 'The North-Eastern Areas (Reorganisation) Act, 1971 makes Lushai Hills the Union Territory of Mizoram and gives Tripura statehood, turning the 1890 line into a full interstate boundary.', ['m7']),
    ('1997', 'Ethnic clashes between Mizos and Brus (Reangs) drive more than 37,000 Bru people from Mizoram’s Mamit, Kolasib and Lunglei districts across this border into relief camps in Tripura’s Kanchanpur and Panisagar subdivisions.', ['ne_bru']),
    ('Jan 2020', 'After eight failed repatriation attempts, a quadripartite agreement between the Centre, Tripura, Mizoram and Bru representatives settles about 34,000 Bru refugees permanently in Tripura rather than returning them to Mizoram.', ['ne_bru']),
)
